const $ = id => document.getElementById(id);
const playerId=window.CIPlayerWorkspaces.id;
const gratitude=['gratitude','gratitude-v2'].includes(playerId);
const gratitudeV2=playerId==='gratitude-v2';
const closingDuration=()=>gratitudeV2?6:5;
const closingStart=()=>total()-closingDuration();
const bellStart=()=>closingStart()+(gratitudeV2?1:0);
const eyeStart=()=>boundaries().find((b,i)=>model.cards[i].label==='Close your eyes')?.start??quietStart();
